# application.yml
p312:
  sistema-saldos: 500            # MOVE 500 TO WKS-B01-SISTEMA / WKS-B03-SISTEMA

// ---------------------------------------------------------------------------
@Component
@RequiredArgsConstructor
public class InicioS084Tasklet implements Tasklet {

    private final ControlSistemasClient control;   // CONSISDIA / CONSISMEN IN LIB-CONTROL
    private final BaseSaldosResolver bases;
    private final P312Properties props;

    @Override
    public RepeatStatus execute(StepContribution c, ChunkContext ctx) {
        var dia = control.consultaSistemaDia(props.sistemaSaldos());
        if (dia.result() != 0) throw new ControlSistemaException("CONSISDIA " + dia.result());
        var men = control.sistemaMensual(props.sistemaSaldos());
        if (men.result() != 0) throw new ControlSistemaException("CONSISMEN " + men.result());

        // OPEN INQUIRY BASESDO: si la base no abre, el step falla aquí (el original sigue).
        bases.verificaLectura(men.nombreBdSaldos());

        var ec = ctx.getStepContext().getStepExecution().getJobExecution().getExecutionContext();
        ec.put("fechaConsulta", dia.fechaConsulta());      // WKS-FECHA-LINEA (B01-FECCON)
        ec.put("fechaProceso151", dia.fechaProceso151());  // WKS-FECHA-PROC para el header
        ec.put("baseSaldos", men.nombreBdSaldos());
        return RepeatStatus.FINISHED;
    }
}

# application.yml
p312:
  salida:
    plantilla: "(S151)S151/FILE/S084/{nodo}/{fecha}."
    nodo: "04"                    # WKS-NODO-ORIGEN-S084 VALUE 04: cobertura Monterrey
    sistema-origen: 151
    sistema-destino: 84

// ---------------------------------------------------------------------------
public sealed interface RegistroS084 permits RegistroS084.Header, RegistroS084.Detalle,
                                              RegistroS084.Trailer {
    /** FUNCION 01: header de 423 posiciones, campos COMP. */
    record Header(int sistemaOrigen, int sistemaDestino, LocalDate fecha) implements RegistroS084 {}
    record Detalle(/* ver s3 */) implements RegistroS084 {}
    /** FUNCION 09. */
    record Trailer(long totalRegistros) implements RegistroS084 {}
}

@Bean
@StepScope
FlatFileHeaderCallback headerS084(P312Properties p,
        @Value("#{jobExecutionContext['fechaProceso151']}") LocalDate fechaPro) {
    return w -> w.write(CodecS084.encode(new RegistroS084.Header(
            p.salida().sistemaOrigen(), p.salida().sistemaDestino(), fechaPro)));
}

// Título: la fecha es AAMMDD (los 6 dígitos bajos de B01-FECCON); se conserva por compatibilidad con S084.
static String titulo(P312Properties p, LocalDate fechaConsulta) {
    return p.salida().plantilla().replace("{nodo}", p.salida().nodo())
            .replace("{fecha}", fechaConsulta.format(DateTimeFormatter.ofPattern("yyMMdd")));
}

/** WKS-DET-SDOS084 (FUNCION 02). Todos los campos son COMP en el archivo. */
public record DetalleS084(
        int producto, int instrumento, int moneda,        // 1, 3, 1
        String contrato,                                  // 9(20) como String
        LocalDate fecha,                                  // 9(06) AAMMDD, pivote en FechasY2k
        int numConceptos,                                 // WKS-DET-CONCEPTOS 9(02): ver riesgo
        int sucursalPromotora,                            // 9(04)
        int diasCiclo,                                    // 9(02)
        long chequesExentos,                              // 9(06)
        BigDecimal tasaNeta, BigDecimal tasaBruta,        // 9(04)V9(04) escala 4
        BigDecimal tasaNetaAnual,
        List<ConceptoS084> conceptos) implements RegistroS084 {

    public static final int MAX_CONCEPTOS = 25;           // OCCURS 25 TIMES

    public DetalleS084 {
        if (conceptos.size() > MAX_CONCEPTOS) throw new IllegalArgumentException("más de 25 conceptos");
        conceptos = List.copyOf(conceptos);
    }
}

/** Clave 9(04), movimientos 9(08), importe S9(15)V99 con signo y escala 2. */
public record ConceptoS084(int clave, long numMovimientos, BigDecimal importe) {}

@Component
@StepScope
@RequiredArgsConstructor
public class ContratoS084Processor implements ItemProcessor<EstadoCuentaB80, DetalleS084> {

    private final SaldoMensualRepository b20;   // B20SXSDOMENCON
    private final ApunteMensualRepository b21;   // B21SXSDMENCON1
    private final ConceptosS084 conceptos;
    private final P312Properties props;

    @Override
    public DetalleS084 process(EstadoCuentaB80 ec) {
        var lista = new ArrayList<ConceptoS084>();
        var saldo = b20.findFirst(ec.contrato(), ec.anioMes(), 1, 3, 1);
        saldo.ifPresent(s -> conceptos.deB20(s, lista));
        boolean tieneApuntes = saldo.map(s -> s.apuntadorImportes() > 0).orElse(false);
        if (tieneApuntes) {
            b21.findAll(ec.contrato(), ec.anioMes(), 1, 3).forEach(a -> conceptos.deB21(a, lista));
        }
        // Comportamiento del fuente: el WRITE está dentro del IF B20-SDO-APUIMP > 0.
        if (!tieneApuntes && props.soloConApuntes()) {
            return null;                         // el contrato no llega a S084
        }
        return DetalleS084.de(ec, saldo, lista);
    }
}

// p312.solo-con-apuntes: true   # replica la conducta actual; false = escribir todos los contratos

# application.yml
p312:
  pim: { producto: 1, instrumento: 3, moneda: 1 }   # único perfil que exporta P312

// ---------------------------------------------------------------------------
@Bean
@StepScope
RepositoryItemReader<EstadoCuentaB80> lectorB80(EstadoCuentaRepository repo, P312Properties p) {
    // FIND NEXT B80SXEDOCTA AT B80-SDO-PRD = 1 AND B80-SDO-INS = 3
    return new RepositoryItemReaderBuilder<EstadoCuentaB80>()
            .name("b80")
            .repository(repo)
            .methodName("findByProductoAndInstrumento")
            .arguments(p.pim().producto(), p.pim().instrumento())
            .sorts(Map.of("contrato", Sort.Direction.ASC))
            .pageSize(1_000)
            .build();
}

/** 02130-DATOS-B80: tasas y días del ciclo vienen del bloque de 146 bytes de S500 (B80-SDO-DATOS). */
record EstadoCuentaB80(String contrato, LocalDate fechaCorte, InfoAdicionalS500 s500) {
    int anioMes() { return fechaCorte.getYear() * 100 + fechaCorte.getMonthValue(); }  // WKS-AAMM-PROC
}

public interface SaldoMensualRepository {
    /** FIND FIRST B20SXSDOMENCON AT contrato, año-mes, producto, instrumento, moneda. */
    Optional<SaldoMensualB20> findFirst(String contrato, int anioMes, int prd, int ins, int mon);
}

// En DetalleS084.de(...): la sucursal promotora se toma siempre de B20 cuando existe.
static int sucursalPromotora(Optional<SaldoMensualB20> b20, P312Properties p) {
    if (p.replicarSucursalCero()) {
        // Conducta actual: cuando hay apuntes, 02140 no mueve B20-SDO-SUCPRO porque
        // W77-ERROR-BASE ya vale 1 al terminar el ciclo de B21.
        return b20.filter(s -> s.apuntadorImportes() == 0).map(SaldoMensualB20::sucursal).orElse(0);
    }
    return b20.map(SaldoMensualB20::sucursal).orElse(0);
}

// NOTFOUND en B20, B21: se trata como ausencia (Optional vacío). Cualquier otro DMSTATUS lanza
// DataAccessException y el step falla; en el fuente solo se registra con 900000-CHE-STA.

# application.yml
p312:
  conceptos-validos: [2, 5, 6, 7, 8, 9, 13, 15, 29, 30, 34, 35, 36, 43, 44, 45]   # W88-CONCEPTOS

// ---------------------------------------------------------------------------
@Component
@RequiredArgsConstructor
public class ConceptosS084 {

    private final P312Properties props;

    /** 02144-MUEVE-CONCEPTOS: posiciones 1..10 de B20; la clave es la posición. */
    void deB20(SaldoMensualB20 s, List<ConceptoS084> destino) {
        for (int i = 1; i <= 10; i++) {
            agrega(i, s.cntMov(i), s.saldo(i), destino);
        }
    }

    private void agrega(int clave, long movs, BigDecimal saldo, List<ConceptoS084> destino) {
        if (!props.conceptosValidos().contains(clave)) return;
        // Se exporta si saldo > 0 o movimientos > 0: un saldo negativo sin movimientos se omite.
        if (saldo.signum() > 0 || movs > 0) {
            if (destino.size() == DetalleS084.MAX_CONCEPTOS) return;
            destino.add(new ConceptoS084(clave, movs, saldo));
        }
    }
}

/** 02160-DET-B21 / 02162-RESTO-B21: 12 posiciones por grupo; clave = grupo * 12 + posición - 2. */
void deB21(ApunteMensualB21 a, List<ConceptoS084> destino) {
    int grupo = a.keyInd();                          // B21-SDO-KEYIND
    for (int pos = 1; pos <= 12 && destino.size() < DetalleS084.MAX_CONCEPTOS; pos++) {
        int clave = grupo * 12 + pos - 2;            // grupo 1: 11..22, grupo 2: 23..34, grupo 3: 35..46
        agrega(clave, a.cntMov(pos), a.saldo(pos), destino);
    }
}

@Component
@StepScope
public class TrailerS084Callback implements FlatFileFooterCallback, ItemWriteListener<DetalleS084> {

    private long grabados;                                 // WKS-CONT-GRAB PIC 9(06)

    @Override
    public void afterWrite(Chunk<? extends DetalleS084> items) {
        grabados += items.size();
        if (grabados > 999_999) {
            throw new IllegalStateException("WKS-CONT-GRAB excede 9(06)");   // el original truncaría
        }
    }

    @Override
    public void writeFooter(Writer w) throws IOException {
        w.write(CodecS084.encode(new RegistroS084.Trailer(grabados)));    // FUNCION 09
    }
}
